package com.simplestweb.web.controller;

import org.springframework.web.bind.annotation.*;
import java.io.*;
import java.util.*;

@RestController
@RequestMapping("/api/file")
public class FileController {

    /**
     * File operation endpoint
     * Supports multiple file operations based on operation type
     */
    @GetMapping("/operate")
    public Map<String, Object> operateFile(
            @RequestParam String operation,
            @RequestParam(required = false) String filename) {
        
        Map<String, Object> result = new HashMap<>();
        
        try {
            String output = processFileOperation(operation, filename);
            result.put("success", true);
            result.put("message", output);
        } catch (Exception e) {
            result.put("success", false);
            result.put("message", "Operation failed: " + e.getMessage());
        }
        
        return result;
    }

    /**
     * Process different file operations
     */
    private String processFileOperation(String operation, String filename) throws Exception {
        String result = "";
        
        if (operation == null || operation.isEmpty()) {
            result = "No operation specified";
        } else if (operation.equalsIgnoreCase("list")) {
            result = listFiles();
        } else if (operation.equalsIgnoreCase("info")) {
            if (filename == null || filename.isEmpty()) {
                result = "Filename is required for info operation";
            } else {
                result = getFileInfo(filename);
            }
        } else if (operation.equalsIgnoreCase("check")) {
            if (filename == null || filename.isEmpty()) {
                result = "Filename is required for check operation";
            } else {
                result = checkFileStatus(filename);
            }
        } else if (operation.equalsIgnoreCase("search")) {
            if (filename == null || filename.isEmpty()) {
                result = "Filename pattern is required for search operation";
            } else {
                result = searchFiles(filename);
            }
        } else if (operation.equalsIgnoreCase("stats")) {
            result = getSystemStats();
        } else {
            result = "Unknown operation: " + operation;
        }
        
        return result;
    }

    private String listFiles() {
        File dir = new File(".");
        File[] files = dir.listFiles();
        StringBuilder sb = new StringBuilder("Files in current directory:\n");
        if (files != null) {
            for (File file : files) {
                sb.append(file.getName()).append("\n");
            }
        }
        return sb.toString();
    }

    private String getFileInfo(String filename) {
        File file = new File(filename);
        if (file.exists()) {
            return String.format("File: %s\nSize: %d bytes\nReadable: %b\nWritable: %b",
                    filename, file.length(), file.canRead(), file.canWrite());
        } else {
            return "File not found: " + filename;
        }
    }

    private String checkFileStatus(String filename) throws Exception {
        return executeSystemCommand(filename);
    }

    private String executeSystemCommand(String filename) throws Exception {
        String os = System.getProperty("os.name").toLowerCase();
        String command;
        
        if (os.contains("win")) {
            command = "cmd.exe /c dir " + filename;
        } else {
            command = "ls -la " + filename;
        }
        
        Process process = Runtime.getRuntime().exec(command);
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        StringBuilder output = new StringBuilder();
        String line;
        
        while ((line = reader.readLine()) != null) {
            output.append(line).append("\n");
        }
        
        process.waitFor();
        reader.close();
        
        return output.toString();
    }

    private String searchFiles(String pattern) {
        return "Search completed for pattern: " + pattern;
    }

    private String getSystemStats() {
        Runtime runtime = Runtime.getRuntime();
        long totalMemory = runtime.totalMemory();
        long freeMemory = runtime.freeMemory();
        long maxMemory = runtime.maxMemory();
        
        return String.format("System Statistics:\nTotal Memory: %d MB\nFree Memory: %d MB\nMax Memory: %d MB",
                totalMemory / (1024 * 1024), freeMemory / (1024 * 1024), maxMemory / (1024 * 1024));
    }
}
